// Content with portions generated by generative AI platform
package org.eclipse.kura.core.configuration;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertTrue;

import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.Hashtable;
import java.util.List;
import java.util.Map;
import java.util.function.BooleanSupplier;

import org.eclipse.kura.KuraException;
import org.eclipse.kura.configuration.ComponentConfiguration;
import org.eclipse.kura.configuration.ConfigurableComponent;
import org.eclipse.kura.configuration.ConfigurationService;
import org.junit.After;
import org.junit.Test;
import org.osgi.framework.BundleContext;
import org.osgi.framework.Constants;
import org.osgi.framework.FrameworkUtil;
import org.osgi.framework.InvalidSyntaxException;
import org.osgi.framework.ServiceReference;
import org.osgi.service.cm.Configuration;
import org.osgi.service.cm.ConfigurationAdmin;
import org.osgi.util.tracker.ServiceTracker;

public class DeclaredServicePidComponentTest {

    private static final String FACTORY_PID = "org.eclipse.kura.core.configuration.ServicePidFactoryComponent";
    private static final String SINGLETON_PID = "org.eclipse.kura.core.configuration.ServicePidSingletonConfiguration";
    private static final String FIELD = "field.test";
    private static final long TIMEOUT_MS = 30000;
    private static final long POLL_INTERVAL_MS = 100;

    private final BundleContext bundleContext = FrameworkUtil.getBundle(DeclaredServicePidComponentTest.class)
            .getBundleContext();
    private final List<String> factoryInstances = new ArrayList<>();

    private ConfigurationService configurationService;
    private ConfigurationAdmin configurationAdmin;

    @Test
    public void factoryInstanceCreatedByConfigurationServiceIsUpdatable() throws Exception {
        givenServices();
        givenFactoryInstanceCreatedByConfigurationService("servicePidFactory1");
        givenServicePidWithSeveralValues("servicePidFactory1");

        whenConfigurationIsUpdated("servicePidFactory1", 7);

        thenComponentIsTracked("servicePidFactory1");
        thenComponentReceives("servicePidFactory1", 7);
        thenComponentConfigurationContains("servicePidFactory1", 7);
    }

    @Test
    public void factoryInstanceCreatedByConfigurationAdminIsUpdatable() throws Exception {
        givenServices();
        givenFactoryInstanceCreatedByConfigurationAdmin("servicePidFactory2");
        givenServicePidWithSeveralValues("servicePidFactory2");

        whenConfigurationIsUpdated("servicePidFactory2", 7);

        thenComponentIsTracked("servicePidFactory2");
        thenComponentReceives("servicePidFactory2", 7);
        thenComponentConfigurationContains("servicePidFactory2", 7);
    }

    @Test
    public void factoryInstanceIsUntrackedWhenItsConfigurationIsDeleted() throws Exception {
        givenServices();
        givenFactoryInstanceCreatedByConfigurationService("servicePidFactory3");
        givenServicePidWithSeveralValues("servicePidFactory3");

        whenConfigurationIsDeletedFromConfigurationAdmin("servicePidFactory3");

        thenComponentIsNotTracked("servicePidFactory3");
    }

    @Test
    public void singletonWithAnotherConfigurationPidIsUpdatable() throws Exception {
        givenServices();
        givenServicePidWithSeveralValues(SINGLETON_PID);

        whenConfigurationIsUpdated(SINGLETON_PID, 7);

        thenComponentIsTracked(SINGLETON_PID);
        thenComponentReceives(SINGLETON_PID, 7);
        thenComponentConfigurationContains(SINGLETON_PID, 7);
    }

    @After
    public void deleteFactoryInstances() throws KuraException {
        for (final String pid : this.factoryInstances) {
            this.configurationService.deleteFactoryConfiguration(pid, false);
        }
    }

    private void givenServices() throws InterruptedException {
        this.configurationService = waitForService(ConfigurationService.class);
        this.configurationAdmin = waitForService(ConfigurationAdmin.class);

        assertNotNull(this.configurationService);
        assertNotNull(this.configurationAdmin);
    }

    private void givenFactoryInstanceCreatedByConfigurationService(final String pid) throws KuraException {
        this.factoryInstances.add(pid);
        this.configurationService.createFactoryConfiguration(FACTORY_PID, pid, null, false);
    }

    private void givenFactoryInstanceCreatedByConfigurationAdmin(final String pid) throws Exception {
        this.factoryInstances.add(pid);

        final Hashtable<String, Object> properties = new Hashtable<>();
        properties.put(ConfigurationService.KURA_SERVICE_PID, pid);

        this.configurationAdmin.createFactoryConfiguration(FACTORY_PID, "?").update(properties);
    }

    private void givenServicePidWithSeveralValues(final String pid) {
        await(() -> getComponentReference(pid) != null);

        final ServiceReference<ConfigurableComponent> reference = getComponentReference(pid);

        assertNotNull(reference);
        assertTrue(reference.getProperty(Constants.SERVICE_PID) instanceof Collection);
        assertEquals(2, ((Collection<?>) reference.getProperty(Constants.SERVICE_PID)).size());
    }

    private void whenConfigurationIsUpdated(final String pid, final int value) throws KuraException {
        await(() -> isTracked(pid));

        this.configurationService.updateConfiguration(pid, Collections.singletonMap(FIELD, value), false);
    }

    private void whenConfigurationIsDeletedFromConfigurationAdmin(final String pid) throws Exception {
        await(() -> isTracked(pid));

        final Configuration[] configurations = this.configurationAdmin
                .listConfigurations("(" + ConfigurationService.KURA_SERVICE_PID + "=" + pid + ")");

        assertNotNull(configurations);

        for (final Configuration configuration : configurations) {
            configuration.delete();
        }
    }

    private void thenComponentIsTracked(final String pid) {
        assertTrue(isTracked(pid));
    }

    private void thenComponentIsNotTracked(final String pid) {
        await(() -> !isTracked(pid));

        assertFalse(isTracked(pid));
    }

    private void thenComponentReceives(final String pid, final int value) {
        await(() -> receivedValue(pid) == value);

        assertEquals(value, receivedValue(pid));
    }

    private void thenComponentConfigurationContains(final String pid, final int value) throws KuraException {
        final ComponentConfiguration configuration = this.configurationService.getComponentConfiguration(pid);

        assertNotNull(configuration);
        assertEquals(Integer.valueOf(value), configuration.getConfigurationProperties().get(FIELD));
    }

    private boolean isTracked(final String pid) {
        return this.configurationService.getConfigurableComponentPids().contains(pid);
    }

    private int receivedValue(final String pid) {
        final Map<String, Object> properties = ServicePidTestComponent.getProperties(pid);

        if (properties == null || !(properties.get(FIELD) instanceof Integer)) {
            return -1;
        }

        return (Integer) properties.get(FIELD);
    }

    private ServiceReference<ConfigurableComponent> getComponentReference(final String pid) {
        try {
            return this.bundleContext
                    .getServiceReferences(ConfigurableComponent.class,
                            "(" + ConfigurationService.KURA_SERVICE_PID + "=" + pid + ")")
                    .stream().findFirst().orElse(null);
        } catch (final InvalidSyntaxException e) {
            throw new IllegalArgumentException(e);
        }
    }

    private <T> T waitForService(final Class<T> service) throws InterruptedException {
        final ServiceTracker<T, T> tracker = new ServiceTracker<>(this.bundleContext, service, null);
        tracker.open();

        try {
            return tracker.waitForService(TIMEOUT_MS);
        } finally {
            tracker.close();
        }
    }

    private static void await(final BooleanSupplier condition) {
        final long deadline = System.currentTimeMillis() + TIMEOUT_MS;

        while (!condition.getAsBoolean() && System.currentTimeMillis() < deadline) {
            try {
                Thread.sleep(POLL_INTERVAL_MS);
            } catch (final InterruptedException e) {
                Thread.currentThread().interrupt();
                return;
            }
        }
    }
}
